# Let's brute force search for magic sequence of length 3
solutions = []
for x0 in range(4):
    for x1 in range(4):
        for x2 in range(4):
            seq = [x0, x1, x2]
            # count occurrences of 0, 1, 2 in the sequence
            count0 = seq.count(0)
            count1 = seq.count(1)
            count2 = seq.count(2)
            if x0 == count0 and x1 == count1 and x2 == count2:
                solutions.append(seq)

print("Solutions found:", solutions)

